TextSuggesterAsyncWaiter::TextSuggesterAsyncWaiter(
    TextSuggester* proxy) : proxy_(proxy) {}

TextSuggesterAsyncWaiter::~TextSuggesterAsyncWaiter() = default;

void TextSuggesterAsyncWaiter::Suggest(
    TextSuggesterQueryPtr query, TextSuggesterResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->Suggest(std::move(query),
      base::BindOnce(
          [](base::RunLoop* loop,
             TextSuggesterResultPtr* out_result
,
             TextSuggesterResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}





